<script setup lang="ts">import {computed} from 'vue';import {Run} from '../types/domain';import {median,probability} from '../utils/format';const props=defineProps<{run:Run}>();const ready=computed(()=>props.run.status==='completed'&&!!props.run.result?.groups);</script><template><div v-if="ready" class="run-summary"><div v-for="(g,i) in run.result.groups" :key="g.cohort.id" :class="['group-summary','group-'+i]"><span>{{g.cohort.code}} / {{g.cohort.process}}</span><h3>{{g.cohort.name}}</h3><b>{{median(g.median)}}</b><small>中位耐久 · {{g.events}} 事件 / {{g.censored}} 删失</small></div><div class="test-summary"><span>LOG-RANK / 双侧</span><b>{{probability(run.result.logrank.p_value)}}</b><small>{{run.result.logrank.estimable?'p 值 · 非因果结论':'无可比较事件或方差为零'}}</small></div><div class="test-summary"><span>数据修订</span><b class="mono">rev {{run.result_revision}}</b><small>曲线 · 归档 · 导出同修订</small></div></div><div v-else class="run-summary pending-summary"><span class="eyebrow">RUN-{{run.id}} / {{run.status}}</span><small>结果修订 rev {{run.result_revision??'—'}} · 目标修订 rev {{run.target_revision}}</small></div></template>
